SELECT "REC_COMP", fp_rate, model_conf, pat_rec, behav_score, 
    ROUND(CAST((fp_rate + model_conf + pat_rec / 100) * 33.33 AS numeric), 2) as test_calc
FROM reg_compliance WHERE last_rev >= '2024-01-01' LIMIT 10;

SELECT "REC_COMP", fp_rate, model_conf, pat_rec, behav_score, net_score, 
    ROUND(CAST((fp_rate * 100 + model_conf * 100 + pat_rec) / 3 AS numeric), 2) as avg_score
FROM reg_compliance WHERE last_rev >= '2024-01-01' LIMIT 10;

SELECT "REC_COMP", behav_score, net_score, 
    ROUND(CAST((behav_score + net_score) / 2 AS numeric), 2) as avg_bn
FROM reg_compliance WHERE last_rev >= '2024-01-01' LIMIT 10;

SELECT "REC_COMP", fp_rate, model_conf, pat_rec, behav_score,
    ROUND(CAST((1 - fp_rate) * 100 * 0.25 + model_conf * 100 * 0.25 + (100 - pat_rec) * 0.25 + pat_rec * 0.25 AS numeric), 2) as test3
FROM reg_compliance WHERE last_rev >= '2024-01-01' LIMIT 10;

